{"path":"src/graph.mjs","content":"function index(records) {
  if(!Array.isArray(records)) throw Error('invalid records');
  return new Map(records.map(r=>[r.id,r]));
}
export function planDependencies(records,requestedIds) {
  const nodes=index(records);
  if(!Array.isArray(requestedIds) || requestedIds.some(id=>typeof id!=='string')) throw Error('invalid requested ids');
  const done=new Set(),active=new Set(),path=[],result=[];
  function visit(id) {
    if(!nodes.has(id)) throw Error(`missing id: ${id}`);
    if(active.has(id)) throw Error(`cycle: ${[...path.slice(path.indexOf(id)),id].join(' -> ')}`);
    if(done.has(id)) return;
    active.add(id);path.push(id);
    for(const dep of nodes.get(id).dependencies) visit(dep);
    path.pop();active.delete(id);done.add(id);result.push(id);
  }
  for(const id of requestedIds) visit(id);
  return result;
}
export function reverseDependencies(records,id) {
  const nodes=index(records);if(!nodes.has(id)) throw Error(`unknown id: ${id}`);
  const reverse=new Map();
  for(const r of records) for(const dep of r.dependencies) {
    if(!reverse.has(dep)) reverse.set(dep,[]);reverse.get(dep).push(r.id);
  }
  const seen=new Set([id]),queue=[id];
  for(let i=0;i<queue.length;i++) for(const next of reverse.get(queue[i])??[]) {
    if(!seen.has(next)) {seen.add(next);queue.push(next);}
  }
  seen.delete(id);return [...seen].sort();
}
"}

{"path":"src/transfer.mjs","content":"import {StringDecoder} from 'node:string_decoder';
import {parseCSV,stringifyCSV} from './csv.mjs';
import {createCatalog} from './catalog.mjs';
const header=['id','name','version','tags','dependencies'];
function addAll(records,catalog) {
  const validated=createCatalog(records).list();
  // Keep input order while validating duplicate and malformed records before writing.
  const byId=new Map(validated.map(r=>[r.id,r]));
  return catalog.applyBatch(records.map(r=>({type:'add',record:byId.get(r.id.trim())})));
}
export function exportCSV(records) {
  return stringifyCSV([header,...records.map(r=>[r.id,r.name,r.version,r.tags.join('|'),r.dependencies.join('|')])]);
}
export function importCSV(text,catalog) {
  const rows=parseCSV(text);
  if(!rows.length || rows[0].length!==header.length || rows[0].some((v,i)=>v!==header[i])) throw Error('invalid CSV header');
  const records=rows.slice(1).map(row=>{
    if(row.length!==5) throw Error('invalid CSV record');
    const [id,name,version,tags,dependencies]=row;
    return {id,name,version,tags:tags ? tags.split('|'):[],dependencies:dependencies ? dependencies.split('|'):[]};
  });
  return addAll(records,catalog);
}
export async function* exportNDJSON(records) {
  for(const record of records) yield JSON.stringify(record)+'\n';
}
export async function importNDJSON(chunks,catalog) {
  const decoder=new StringDecoder('utf8');let pending='';const records=[];
  function consume(text) {
    pending+=text;let end;
    while((end=pending.indexOf('\n'))>=0) {
      const line=pending.slice(0,end);pending=pending.slice(end+1);
      if(line.trim()) records.push(JSON.parse(line));
    }
  }
  for await(const chunk of chunks) {
    if(Buffer.isBuffer(chunk)) consume(decoder.write(chunk));
    else if(typeof chunk==='string') {consume(decoder.end());consume(chunk);}
    else throw Error('invalid NDJSON chunk');
  }
  consume(decoder.end());if(pending.trim()) records.push(JSON.parse(pending));
  return addAll(records,catalog);
}
"}

{"path":"src/server.mjs","content":"import http from 'node:http';
import {searchRecords} from './search.mjs';
import {planDependencies} from './graph.mjs';
import {exportCSV,importCSV,exportNDJSON,importNDJSON} from './transfer.mjs';
const maxBody=1024*1024;
async function body(req) {
  const chunks=[];let size=0;
  for await(const chunk of req) {
    size+=chunk.length;
    if(size>maxBody) {const e=Error('request body exceeds 1 MiB');e.status=413;throw e;}
    chunks.push(chunk);
  }
  return Buffer.concat(chunks);
}
function queryFor(params) {
  const query={};
  for(const key of ['text','versionMin','versionMax','sortBy','order']) if(params.has(key)) query[key]=params.get(key);
  if(params.has('tags')) query.tags=params.get('tags').split(',');
  for(const key of ['offset','limit']) if(params.has(key)) {
    const value=params.get(key);
    if(!/^[0-9]+$/.test(value)) throw Error('invalid paging');
    query[key]=Number(value);
  }
  return query;
}
export function createServer(catalog) {
  return http.createServer(async(req,res)=>{
    const send=(status,data,type='application/json')=>{
      res.writeHead(status,{'content-type':type});res.end(type==='application/json'?JSON.stringify(data):data);
    };
    try {
      const url=new URL(req.url,'http://localhost'),path=url.pathname,method=req.method;
      if(method==='GET' && path==='/health') return send(200,{ok:true});
      if(method==='GET' && path==='/records') return send(200,searchRecords(catalog.list(),queryFor(url.searchParams)));
      if(method==='POST' && path==='/records') {
        const record=JSON.parse((await body(req)).toString('utf8'));
        return send(201,catalog.add(record));
      }
      if(path.startsWith('/records/') && ['GET','PATCH','DELETE'].includes(method)) {
        const id=decodeURIComponent(path.slice('/records/'.length));
        if(!catalog.get(id)) return send(404,{error:`unknown id: ${id}`});
        if(method==='GET') return send(200,catalog.get(id));
        if(method==='PATCH') return send(200,catalog.update(id,JSON.parse((await body(req)).toString('utf8'))));
        catalog.remove(id);res.writeHead(204);return res.end();
      }
      if(method==='GET' && path==='/plan') {
        const raw=url.searchParams.get('ids');
        return send(200,{ids:planDependencies(catalog.list(),raw ? raw.split(','):[])});
      }
      if(method==='GET' && path==='/export.csv') return send(200,exportCSV(catalog.list()),'text/csv');
      if(method==='POST' && path==='/import.csv') return send(201,{added:importCSV((await body(req)).toString('utf8'),catalog).length});
      if(method==='POST' && path==='/import.ndjson') {
        const data=await body(req);return send(201,{added:(await importNDJSON([data],catalog)).length});
      }
      if(method==='GET' && path==='/export.ndjson') {
        res.writeHead(200,{'content-type':'application/x-ndjson'});
        for await(const line of exportNDJSON(catalog.list())) res.write(line);
        return res.end();
      }
      return send(404,{error:'unknown route'});
    } catch(error) {
      if(res.headersSent) {res.end();return;}
      send(error.status??(/^duplicate id:/.test(error.message)?409:400),{error:error.message});
    }
  });
}
"}

{"path":"src/cli.mjs","content":"import {readFile,writeFile,rename,unlink} from 'node:fs/promises';
import {resolve,dirname,basename,join} from 'node:path';
import {pathToFileURL} from 'node:url';
import {randomUUID} from 'node:crypto';
import {createCatalog} from './catalog.mjs';
import {searchRecords} from './search.mjs';
import {planDependencies} from './graph.mjs';
import {importCSV,exportCSV} from './transfer.mjs';
export async function main(args=process.argv.slice(2)) {
  const [command,...rest]=args,options={};
  for(let i=0;i<rest.length;i+=2) {
    if(!rest[i].startsWith('--') || rest[i+1]===undefined || rest[i+1].startsWith('--')) throw Error('invalid arguments');
    const key=rest[i].slice(2);if(Object.hasOwn(options,key)) throw Error(`duplicate option: ${key}`);options[key]=rest[i+1];
  }
  const allowed={list:['text','tags'],add:['record'],remove:['id'],plan:['ids'],'import-csv':['input'],'export-csv':[]};
  if(!Object.hasOwn(allowed,command)) throw Error('unknown command');
  if(!options.file) throw Error('--file is mandatory');
  for(const key of Object.keys(options)) if(key!=='file' && !allowed[command].includes(key)) throw Error(`unknown option: ${key}`);
  const file=resolve(options.file);let seed=[];
  try {seed=JSON.parse(await readFile(file,'utf8'));} catch(error) {if(error.code!=='ENOENT') throw error;}
  const catalog=createCatalog(seed);let output,write=false;
  const required=key=>{if(options[key]===undefined) throw Error(`--${key} is mandatory`);return options[key];};
  switch(command) {
    case 'list': output=searchRecords(catalog.list(),{text:options.text??'',tags:options.tags?.split(',')??[]});break;
    case 'add': output=catalog.add(JSON.parse(required('record')));write=true;break;
    case 'remove': output=catalog.remove(required('id'));write=true;break;
    case 'plan': output={ids:planDependencies(catalog.list(),required('ids').split(',').filter(Boolean))};break;
    case 'import-csv': output={added:importCSV(await readFile(required('input'),'utf8'),catalog).length};write=true;break;
    case 'export-csv': output=exportCSV(catalog.list());break;
  }
  if(write) {
    const temporary=join(dirname(file),`.${basename(file)}.${randomUUID()}.tmp`);
    try {await writeFile(temporary,JSON.stringify(catalog.list(),null,2)+'\n',{flag:'wx'});await rename(temporary,file);}
    finally {await unlink(temporary).catch(error=>{if(error.code!=='ENOENT') throw error;});}
  }
  process.stdout.write((command==='export-csv'?output:JSON.stringify(output))+'\n');
}
if(process.argv[1] && import.meta.url===pathToFileURL(resolve(process.argv[1])).href) {
  main().catch(error=>{process.stderr.write(error.message+'\n');process.exitCode=1;});
}
"}

