    if(!rest[i].startsWith('--') || rest[i+1]===undefined || rest[i+1].startsWith('--')) throw Error('invalid arguments');
    const key=rest[i].slice(2);if(Object.hasOwn(options,key)) throw Error(`duplicate option: ${key}`);options[key]=rest[i+1];
